From 3f2f169672e36e910635a4c6e27307250860b406 Mon Sep 17 00:00:00 2001
From: Qrntz <qrntz@lavabit.com>
Date: Sat, 26 Jan 2013 15:38:43 +0200
Subject: [PATCH] Fix signedness error introduced by 599b800b, also fix
 spacing.


diff --git a/src/engine/qcommon/net_chan.c b/src/engine/qcommon/net_chan.c
index 1f28fc973..b7476f758 100644
--- a/src/engine/qcommon/net_chan.c
+++ b/src/engine/qcommon/net_chan.c
@@ -735,7 +735,7 @@ void QDECL PRINTF_LIKE(3) NET_OutOfBandPrint( netsrc_t sock, netadr_t adr, const
 	va_list argptr;
 	char    string[ MAX_MSGLEN ];

-	NET_SetOOBHeader(string);
+	NET_SetOOBHeader( string );

 	va_start( argptr, format );
 	Q_vsnprintf( string + 4, sizeof( string ) - 4, format, argptr );
@@ -747,7 +747,7 @@ void QDECL PRINTF_LIKE(3) NET_OutOfBandPrint( netsrc_t sock, netadr_t adr, const

 /*
 ===============
-NET_OutOfBandPrint
+NET_OutOfBandData

 Sends a data message in an out-of-band datagram (only used for "connect")
 ================
@@ -758,7 +758,7 @@ void QDECL NET_OutOfBandData( netsrc_t sock, netadr_t adr, byte *format, int len
 	int   i;
 	msg_t mbuf;

-	NET_SetOOBHeader(string);
+	NET_SetOOBHeader( ( char * ) string );

 	for ( i = 0; i < len; i++ )
 	{
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by a signedness error introduced in a previous commit, which likely resulted from improper handling of data types when passing arguments to the `NET_SetOOBHeader` function. This could lead to unexpected behavior or crashes if the data being processed does not match the expected type, particularly when dealing with byte arrays or pointers.

        Commit message:
        Fix signedness error introduced by 599b800b, also fix
 spacing.  

        Patch:
         	char    string[ MAX_MSGLEN ];

-	NET_SetOOBHeader(string);
+	NET_SetOOBHeader( string );

 	va_start( argptr, format );
 /*
 ===============
-NET_OutOfBandPrint
+NET_OutOfBandData

 Sends a data message in an out-of-band datagram (only used for "connect")
 */
 void QDECL NET_OutOfBandData( netsrc_t sock, netadr_t adr, byte *format, int len )
 {
 	byte  string[ MAX_MSGLEN * 2 ];
 	int   i;
 	msg_t mbuf;

-	NET_SetOOBHeader(string);
+	NET_SetOOBHeader( ( char * ) string );

 	for ( i = 0; i < len; i++ )
 	{
 		string[ i + 4 ] = format[ i ];
 	}

 	mbuf.data = string;
 	mbuf.cursize = len + 4;
 	Huff_Compress( &mbuf, 12 );
 	// send the datagram
 	NET_SendPacket( sock, mbuf.cursize, mbuf.data, adr );
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>

Code statements:
- NET_SetOOBHeader(string);
+ NET_SetOOBHeader( ( char * ) string );

Code statements:
- NET_SetOOBHeader(string);
+ NET_SetOOBHeader( ( char * ) string );
